import java.util.regex.Pattern;

public class ClassX {
    /**
     * Премахва скриптовите тагове от потребителския вход.
     * 
     * Функцията използва замяна на низове, за да премахне таговете <script>.
     *
     * @param input потребителски вход
     * @return входа без скриптови тагове
     */
    public String removeScriptTags(String input) {
        if (input == null) {
            return null;
        }
        return Pattern.compile("<script.*?>.*?</script>", Pattern.DOTALL | Pattern.CASE_INSENSITIVE)
                      .matcher(input)
                      .replaceAll("");
    }
}
