public String annotateWithValidation(Map<String, String> kwargs) {
    for (Map.Entry<String, String> entry : kwargs.entrySet()) {
        String alias = entry.getKey();

        // Validate alias: disallow semicolons and other SQL keywords
        if (alias.contains(";") || isSQLKeyword(alias)) {
            throw new IllegalArgumentException("Invalid alias");
        }

        this.query += " AS " + alias;
    }
    return this.query;
}

private boolean isSQLKeyword(String alias) {
    String[] sqlKeywords = {"SELECT", "INSERT", "UPDATE", "DELETE", "FROM", "WHERE", "JOIN", "DROP", "CREATE", "ALTER"};
    for (String keyword : sqlKeywords) {
        if (alias.equalsIgnoreCase(keyword)) {
            return true;
        }
    }
    return false;
}
