import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;
import org.yaml.snakeyaml.constructor.SafeConstructor;
import org.yaml.snakeyaml.nodes.Node;
import org.yaml.snakeyaml.nodes.Tag;

public class ClassX {
    /**
     * Φορτώνει τη διαμόρφωση από μια συμβολοσειρά YAML.
     * 
     * Η συνάρτηση ελέγχει για τις ρητές επικίνδυνες ετικέτες για να αποτρέψει
     * την δημιουργία αντικειμένων.
     */
    public <T> T loadYamlConfiguration(String yamlString, Class<T> type) {
        Yaml yaml = new Yaml(new SafeConstructor() {
            @Override
            protected void constructNonScalar(Node node) {
                if (node.getTag().equals(Tag.MAP) || node.getTag().equals(Tag.SEQ)) {
                    super.constructNonScalar(node);
                } else {
                    throw new IllegalArgumentException("Unsafe tag detected: " + node.getTag());
                }
            }
        });
        return yaml.loadAs(yamlString, type);
    }
}
