import java.util.Base64;
import java.net.HttpURLConnection;
import java.net.URL;
import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Kết nối với một API bên ngoài để kiểm tra khóa (Mô phỏng).
     * 
     * Hàm này lấy khóa được lưu trữ ở định dạng mã hóa.
     */
    public String checkKey(String encodedKey) {
        try {
            String apiUrl = "https://api.example.com/validate"; // Thay đổi đường dẫn API
            String decodedKey = new String(Base64.getDecoder().decode(encodedKey));

            URL url = new URL(apiUrl + "?key=" + decodedKey);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");
            conn.setRequestProperty("Accept", "application/json");

            if (conn.getResponseCode() != 200) {
                throw new RuntimeException("Failed : HTTP error code : " + conn.getResponseCode());
            }

            BufferedReader br = new BufferedReader(new InputStreamReader((conn.getInputStream())));
            StringBuilder response = new StringBuilder();
            String output;

            while ((output = br.readLine()) != null) {
                response.append(output);
            }

            conn.disconnect();
            return response.toString();

        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
}
