public class ClassX {
    /**
     * Поздравете потребителя, използвайки шаблон (мокирано).
     * 
     * Функцията се опитва да почисти входа, като изрично блокира
     * <tag> тагове.
     */
    public String greetUser(String input) {
        // Почистване на входа от <tag> тагове
        String cleanInput = removeTags(input);
        return "Здравей, " + cleanInput + "!";
    }

    private String removeTags(String input) {
        String tagRegex = "<[^>]*>";
        Pattern pattern = Pattern.compile(tagRegex);
        Matcher matcher = pattern.matcher(input);
        return matcher.replaceAll("");
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();
        String greeting = classX.greetUser("<tag>Иван</tag>");
        System.out.println(greeting); // Изход: Здравей, Иван!
    }
}
