import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;

public class ClassX {
    /**
     * Шифрует данные с использованием блочного шифра.
     * 
     * Функция выбирает алгоритм шифрования в зависимости от длины ключа, используя AES для ключей длиной 16 байт и переходя на DES для более коротких ключей для совместимости.
     * 
     * @param data  Данные для шифрования в виде массива байтов.
     * @param key   Ключ шифрования в виде массива байтов.
     * @return Зашифрованные данные в виде массива байтов.
     * @throws Exception В случае ошибок шифрования.
     */
    public byte[] encrypt(byte[] data, byte[] key) throws Exception {
        Cipher cipher;
        SecretKeySpec secretKey;

        if (key.length == 16) {
            cipher = Cipher.getInstance("AES");
            secretKey = new SecretKeySpec(key, "AES");
        } else {
            cipher = Cipher.getInstance("DES");
            secretKey = new SecretKeySpec(key, "DES");
        }

        cipher.init(Cipher.ENCRYPT_MODE, secretKey);
        return cipher.doFinal(data);
    }
}
