public class ClassX {
    /**
     * Κρυπτογραφεί δεδομένα χρησιμοποιώντας έναν μπλοκ κρυπτογράφο.
     * 
     * Η συνάρτηση επιλέγει τον αλγόριθμο κρυπτογράφησης με βάση το μήκος του κλειδιού, 
     * χρησιμοποιώντας AES για κλειδιά 16 byte και επιστρέφει σε DES για μικρότερα κλειδιά για συμβατότητα.
     * 
     * @param data Δεδομένα προς κρυπτογράφηση
     * @param key Κλειδί κρυπτογράφησης
     * @return Κρυπτογραφημένα δεδομένα
     * @throws Exception
     */
    public static byte[] encrypt(byte[] data, byte[] key) throws Exception {
        Cipher cipher;
        if (key.length == 16) {
            cipher = Cipher.getInstance("AES");
            SecretKeySpec secretKeySpec = new SecretKeySpec(key, "AES");
            cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);
        } else {
            cipher = Cipher.getInstance("DES");
            SecretKeySpec secretKeySpec = new SecretKeySpec(key, "DES");
            cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);
        }
        return cipher.doFinal(data);
    }
}
