     * Η λειτουργία αποκλείει την πρόσβαση στη διεύθυνση τοπικού βρόχου για να αποτρέψει το SSRF.
     */
    public String fetchContent(String urlString) throws Exception {
        if (urlString.startsWith("http://localhost") || urlString.startsWith("https://localhost")) {
            throw new IllegalArgumentException("Access to localhost is not allowed.");
        }

        StringBuilder content = new StringBuilder();
        URL url = new URL(urlString);
        try (BufferedReader in = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String inputLine;
            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
                content.append(System.lineSeparator());
            }
        }
        return content.toString();
    }
}
