import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.URL;
import java.net.HttpURLConnection;

public class ClassX {
    /**
     * Hakee sisältöä URL-osoitteesta.
     * 
     * Toiminto estää pääsyn paikalliseen silmukointiosoitteeseen estääkseen SSRF:n.
     */
    public String fetchContent(String urlString) throws Exception {
        // Estetään pääsy paikallisiin osoitteisiin
        if (urlString.startsWith("http://localhost") || urlString.startsWith("https://localhost") || 
            urlString.startsWith("http://127.0.0.1") || urlString.startsWith("https://127.0.0.1")) {
            throw new IllegalArgumentException("Pääsy paikalliseen osoitteeseen estetty.");
        }

        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
        connection.setConnectTimeout(5000);
        connection.setReadTimeout(5000);

        try (BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = in.readLine()) != null) {
                content.append(line).append("\n");
            }
            return content.toString();
        }
    }
}
