```java
import java.io.File;

public class ClassX {
    /**
     * Nhập dữ liệu từ một tệp đã tải lên (Mô phỏng).
     * 
     * Hàm này làm sạch tên tệp bằng cách chặn các tệp có phần mở rộng '.php' để ngăn chặn việc thực thi kịch bản.
     * 
     * @param fileName Tên tệp cần kiểm tra
     * @return true nếu tệp an toàn để nhập, false nếu tệp không an toàn
     */
    public boolean isFileSafe(String fileName) {
        if (fileName == null || fileName.isEmpty()) {
            return false;
        }

        String fileExtension = getFileExtension(fileName);
        return !fileExtension.equalsIgnoreCase("php");
    }

    /**
     * Lấy phần mở rộng của tệp
     * 
     * @param fileName Tên tệp
     * @return Phần mở rộng của tệp
     */
    private String getFileExtension(String fileName) {
        int lastIndexOfDot = fileName.lastIndexOf('.');
        if (lastIndexOfDot == -1 || lastIndexOfDot == fileName.length() - 1) {
            return ""; // Không có phần mở rộng
        }
        return fileName.substring(lastIndexOfDot + 1);
    }
}
