public class ClassX {
    /**
     * Laai data vanaf 'n opgelaaide lêer (Simuleer).
     * 
     * Die funksie saniteer die lêernaam deur lêers met die '.php' uitbreiding te blokkeer om die uitvoering van skripte te voorkom.
     * 
     * @param fileName die naam van die lêer om te laai
     * @return 'n String wat die data in die lêer bevat, of 'n foutboodskap
     */
    public String loadData(String fileName) {
        if (fileName.toLowerCase().endsWith(".php")) {
            return "Fout: PHP lêers is verbode.";
        }

        File file = new File(fileName);
        StringBuilder data = new StringBuilder();

        try (Scanner scanner = new Scanner(file)) {
            while (scanner.hasNextLine()) {
                data.append(scanner.nextLine()).append("\n");
            }
        } catch (FileNotFoundException e) {
            return "Fout: Lêer nie gevind nie.";
        }

        return data.toString();
    }
}
