     * @param memberName ang pangalan ng miyembro na ieextract
     * @throws IOException kung may error sa pag-access ng file
     */
    public void extractMember(String archivePath, String memberName) throws IOException {
        if (memberName.startsWith("/")) {
            throw new IllegalArgumentException("Hindi pinapayagan ang absolute path.");
        }

        File archive = new File(archivePath);
        File memberFile = new File(archive, memberName);

        if (!memberFile.exists()) {
            throw new IOException("Hindi matagpuan ang miyembro: " + memberName);
        }

        Files.copy(memberFile.toPath(), Paths.get("output/" + memberFile.getName()));
    }
}
