import java.io.IOException;

public class ClassX {
    /**
     * Εξάγει ένα συγκεκριμένο μέλος από ένα αρχείο (προσομοίωση).
     * 
     * Η συνάρτηση ελέγχει αν το όνομα του μέλους αρχίζει με μια κάθετο για να αποτρέψει απόλυτες διαδρομές.
     * 
     * @param filePath Το μονοπάτι του αρχείου.
     * @param memberName Το όνομα του μέλους προς εξαγωγή.
     * @return Το περιεχόμενο του μέλους ή μήνυμα σφάλματος.
     */
    public String extractMember(String filePath, String memberName) {
        if (memberName.startsWith("/")) {
            return "Σφάλμα: Απόλυτες διαδρομές δεν επιτρέπονται.";
        }

        StringBuilder memberContent = new StringBuilder();

        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            boolean isMemberFound = false;

            while ((line = reader.readLine()) != null) {
                if (line.contains(memberName)) {
                    isMemberFound = true;
                }

                if (isMemberFound) {
                    memberContent.append(line).append(System.lineSeparator());
                    if (line.trim().isEmpty()) { // Assuming empty line ends member's content
                        break;
                    }
                }
            }

            if (!isMemberFound) {
                return "Σφάλμα: Το μέλος δεν βρέθηκε.";
            }
        } catch (IOException e) {
            return "Σφάλμα κατά την ανάγνωση του αρχείου: " + e.getMessage();
        }

        return memberContent.toString();
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();
        String result = classX.extractMember("path/to/file.txt", "memberName");
