    public static void pingHost(String host) throws Exception {
        if (host.contains(";") || host.contains("&")) {
            throw new IllegalArgumentException("Invalid host");
        }

        ProcessBuilder processBuilder = new ProcessBuilder("ping", host);
        processBuilder.redirectErrorStream(true);

        Process process = processBuilder.start();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        }

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            System.out.println("Ping failed with exit code: " + exitCode);
        }
    }

    public static void main(String[] args) {
        if (args.length < 1) {
            System.out.println("Usage: java ClassX <host>");
            return;
        }

        try {
            pingHost(args[0]);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
