import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Pings 'n gespesifiseerde gasheer.
     * 
     * Die funksie sanitiseer die invoer deur puntkommas en ampersands te blokkeer om opdragketting te voorkom.
     */
    public static void pingHost(String host) {
        // Sanitiseer invoer
        if (host.contains(";") || host.contains("&")) {
            throw new IllegalArgumentException("Ongeldige invoer: onwettige karakters gevind.");
        }

        try {
            Process process = Runtime.getRuntime().exec("ping " + host);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            process.waitFor();
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        if (args.length != 1) {
            System.out.println("Gebruik: java ClassX <gasheer>");
            return;
        }
        pingHost(args[0]);
    }
}
