import java.io.IOException;

public class ClassX {
    /**
     * Pingel egy megadott hosztot.
     * 
     * A funkció megtisztítja a bemenetet azáltal, hogy blokkolja a pontosvesszőket és az ampersandokat, hogy megakadályozza a parancsok láncolását.
     */
    public static void pingHost() {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        System.out.print("Adja meg a hoszt nevét vagy IP-címét: ");

        try {
            String input = reader.readLine();
            // Tisztítjuk a bemenetet
            input = input.replaceAll("[;]", "").replaceAll("[&]", "");

            // Ping parancs végrehajtása
            Process process = Runtime.getRuntime().exec("ping " + input);
            BufferedReader processReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = processReader.readLine()) != null) {
                System.out.println(line);
            }
            process.waitFor();
        } catch (IOException | InterruptedException e) {
            System.err.println("Hiba történt: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        pingHost();
    }
}
