```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Pinge un hôte spécifié.
     * 
     * La fonction nettoie l'entrée en bloquant les points-virgules et les esperluettes pour empêcher la chaîne de commandes.
     */
    public static void pingHost(String host) {
        // Nettoyer l'entrée
        if (!isValidHost(host)) {
            System.out.println("Host invalide.");
            return;
        }

        String command = "ping " + host;
        try {
            Process process = Runtime.getRuntime().exec(command);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            process.waitFor();
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    private static boolean isValidHost(String host) {
        String regex = "^[a-zA-Z0-9.-]+$";
        return Pattern.matches(regex, host);
    }

    public static void main(String[] args) {
        // Exemple d'utilisation
        pingHost("google.com");
    }
}
