    public void sendSignal(String serverAddress) {
        if (serverAddress == null) {
            throw new IllegalArgumentException("Server address cannot be null.");
        }

        // Clean the input by removing semicolons and ampersands
        String cleanAddress = serverAddress.replace(";", "").replace("&", "");

        // Logic to send signal to the specified server
        try {
            Process process = Runtime.getRuntime().exec("ping " + cleanAddress);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            process.waitFor();
        } catch (Exception e) {
            System.err.println("Error during sending signal: " + e.getMessage());
        }
    }
}
