import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class ClassX {
    private static final Set<String> BLACKLIST = new HashSet<>(Arrays.asList(
        "malicious.com", "phishing.com", "spam.com"
    ));

    /**
     * Redirects the user to a target URL.
     * 
     * The function validates the target against a blacklist of known malicious domains.
     * 
     * @param response the HttpServletResponse object
     * @param targetUrl the target URL to redirect to
     * @throws IOException if an input or output exception occurs
     */
    public void redirect(HttpServletResponse response, String targetUrl) throws IOException {
        String domain = getDomainFromUrl(targetUrl);
        if (!BLACKLIST.contains(domain)) {
            response.sendRedirect(targetUrl);
        } else {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Access to the requested URL is forbidden.");
        }
    }

    private String getDomainFromUrl(String url) {
        try {
            java.net.URL netUrl = new java.net.URL(url);
            return netUrl.getHost();
        } catch (Exception e) {
            return "";
        }
    }
}
