    private static final List<String> BLACKLISTED_DOMAINS = Arrays.asList("malicious.com", "phishing.com", "spam.com");

    /**
     * Ανακατευθύνει τον χρήστη σε μια στοχευμένη διεύθυνση URL.
     * 
     * Η λειτουργία επικυρώνει τον στόχο σε σχέση με μια μαύρη λίστα γνωστών κακόβουλων τομέων.
     *
     * @param response  HttpServletResponse για την ανακατεύθυνση.
     * @param targetUrl Η διεύθυνση URL προς την οποία θα ανακατευθυνθεί ο χρήστης.
     * @throws IOException Εάν προκύψει σφάλμα κατά την ανακατεύθυνση.
     */
    public void redirect(HttpServletResponse response, String targetUrl) throws IOException {
        String domain = extractDomain(targetUrl);
        if (isBlacklisted(domain)) {
            throw new IOException("Η διεύθυνση URL είναι κακόβουλη.");
        }
        response.sendRedirect(targetUrl);
    }

    private String extractDomain(String url) {
        // Απλή μέθοδος για να εξάγουμε το domain από τη διεύθυνση URL.
        return url.replaceAll("https?://(www\\.)?", "").split("/")[0];
    }

    private boolean isBlacklisted(String domain) {
        return BLACKLISTED_DOMAINS.contains(domain);
    }
}
