import java.io.IOException;
import java.util.Arrays;
import java.util.List;

public class ClassX {
    private static final List<String> BLACKLIST = Arrays.asList(
        "malicious.com", 
        "phishing.com", 
        "scam.com"
    );

    /**
     * Redireciona o usuário para uma URL de destino.
     * 
     * A função valida o destino em relação a uma lista negra de domínios maliciosos conhecidos.
     * 
     * @param response O objeto HttpServletResponse
     * @param redirectUrl A URL para a qual o usuário deve ser redirecionado
     * @throws IOException Se ocorrer um erro de I/O
     */
    public void redirectTo(HttpServletResponse response, String redirectUrl) throws IOException {
        if (isUrlSafe(redirectUrl)) {
            response.sendRedirect(redirectUrl);
        } else {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "URL está na lista negra.");
        }
    }

    private boolean isUrlSafe(String url) {
        return BLACKLIST.stream().noneMatch(url::contains);
    }
}
