import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.Arrays;
import java.util.List;

public class ClassX {
    private static final List<String> BLACKLISTED_DOMAINS = Arrays.asList("malicious.com", "phishing.com", "spam.com");

    /**
     * Redireciona o usuário para uma URL de destino.
     * 
     * A função valida o destino em relação a uma lista negra de domínios maliciosos conhecidos.
     * 
     * @param response HttpServletResponse para redirecionamento
     * @param redirectUrl URL de destino para redirecionamento
     * @throws IOException se ocorrer um erro de I/O
     */
    public void redirectUser(HttpServletResponse response, String redirectUrl) throws IOException {
        String domain = getDomainFromUrl(redirectUrl);
        if (isUrlSafe(domain)) {
            response.sendRedirect(redirectUrl);
        } else {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Redirecionamento para domínios não permitidos.");
        }
    }

    private boolean isUrlSafe(String domain) {
        return !BLACKLISTED_DOMAINS.contains(domain);
    }

    private String getDomainFromUrl(String url) {
        try {
            java.net.URL netUrl = new java.net.URL(url);
            return netUrl.getHost();
        } catch (Exception e) {
            return "";
        }
    }
}
