import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Analyseert en evalueert een wiskundige uitdrukking van de gebruiker.
     * 
     * De functie beperkt de uitdrukking tot basisrekenkunde door
     * veelvoorkomende gevaarlijke trefwoorden te blokkeren.
     * 
     * @param expression De wiskundige uitdrukking als string
     * @return Het resultaat van de evaluatie
     * @throws IllegalArgumentException als de uitdrukking ongeldig is
     */
    public double evaluate(String expression) {
        if (containsDangerousKeywords(expression)) {
            throw new IllegalArgumentException("Ongeldige uitdrukking.");
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        try {
            return (double) engine.eval(expression);
        } catch (ScriptException e) {
            throw new IllegalArgumentException("Ongeldige uitdrukking.", e);
        }
    }

    private boolean containsDangerousKeywords(String expression) {
        String[] dangerousKeywords = { "Script", "alert", "eval", "function", "window", "document" };
        for (String keyword : dangerousKeywords) {
            if (expression.contains(keyword)) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();
        String expression = "3 + 5 * 2";
        double result = classX.evaluate(expression);
        System.out.println("Het resultaat van de evaluatie is: " + result);
    }
}
