     * הפונקציה מגבילה את הביטוי לאריתמטיקה בסיסית על ידי חסימת מילות מפתח מסוכנות נפוצות.
     */
    public double evaluateExpression(String expression) throws ScriptException {
        // לחסום מילות מפתח מסוכנות
        if (expression.matches(".*[a-zA-Z]+.*") || expression.contains("eval") || expression.contains("exec")) {
            throw new IllegalArgumentException("Invalid expression: contains unsafe characters or keywords.");
        }

        // יצירת מנוע סקריפט
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // הערכת הביטוי
        return (double) engine.eval(expression);
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();
        try {
            System.out.println("Result: " + classX.evaluateExpression("3 + 5 * 2"));
        } catch (Exception e) {
            System.err.println(e.getMessage());
        }
    }
}
