     * 
     * Fungsi ini membersihkan host dengan memeriksa karakter tidak valid seperti spasi.
     */
    public String fetchContent(String urlString) throws Exception {
        String cleanedUrl = validateAndCleanUrl(urlString);
        if (cleanedUrl == null) {
            throw new MalformedURLException("Invalid URL");
        }

        URL url = new URL(cleanedUrl);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        int responseCode = connection.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK) {
            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            StringBuilder content = new StringBuilder();
            String line;

            while ((line = in.readLine()) != null) {
                content.append(line);
            }
            in.close();
            return content.toString();
        } else {
            throw new Exception("Failed to fetch content: " + responseCode);
        }
    }

    private String validateAndCleanUrl(String urlString) {
        String trimmedUrl = urlString.trim();
        String regex = "^(http|https)://.*";
        Pattern pattern = Pattern.compile(regex);
        return pattern.matcher(trimmedUrl).matches() ? trimmedUrl : null;
    }
