import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.net.MalformedURLException;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Hakee sisältöä luodusta URL-osoitteesta isäntää validoimalla.
     * 
     * Tämä toiminto puhdistaa isännän tarkistamalla virheelliset merkit, kuten välilyönnit.
     * 
     * @param urlString URL-osoite, josta sisältö haetaan.
     * @return Sisältö URL-osoitteesta tai virheilmoitus.
     */
    public String fetchContent(String urlString) {
        if (!isValidUrl(urlString)) {
            return "Virheellinen URL-osoite";
        }

        StringBuilder content = new StringBuilder();

        try {
            URL url = new URL(urlString);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String inputLine;

            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
            }
            in.close();
        } catch (MalformedURLException e) {
            return "Virheellinen URL-osoite: " + e.getMessage();
        } catch (Exception e) {
            return "Virhe haettaessa sisältöä: " + e.getMessage();
        }

        return content.toString();
    }

    private boolean isValidUrl(String urlString) {
        String regex = "^(http|https)://.*$";
        Pattern pattern = Pattern.compile(regex);
        return pattern.matcher(urlString).matches();
    }
}
