import java.util.regex.Pattern;

public class ClassX {
    /**
     * Obtiene contenido de una URL generada después de validar el host.
     * 
     * Esta función sanitiza el host al verificar la presencia de caracteres inválidos como espacios.
     */
    public String obtenerContenido(String urlString) {
        if (!esHostValido(urlString)) {
            throw new IllegalArgumentException("Host no válido.");
        }

        StringBuilder contenido = new StringBuilder();
        try {
            URL url = new URL(urlString);
            HttpURLConnection httpURLConnection = (HttpURLConnection) url.openConnection();
            httpURLConnection.setRequestMethod("GET");

            try (BufferedReader in = new BufferedReader(new InputStreamReader(httpURLConnection.getInputStream()))) {
                String inputLine;
                while ((inputLine = in.readLine()) != null) {
                    contenido.append(inputLine);
                }
            }
        } catch (MalformedURLException e) {
            e.printStackTrace();
        } catch (Exception e) {
            e.printStackTrace();
        }

        return contenido.toString();
    }

    private boolean esHostValido(String urlString) {
        String host = null;
        try {
            URL url = new URL(urlString);
            host = url.getHost();
        } catch (MalformedURLException e) {
            return false;
        }
        return host != null && !Pattern.compile("[\\s]").matcher(host).find();
    }
}
