import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.net.URLEncoder;

public class ClassX {
    /**
     * Получает содержимое с сгенерированного URL после проверки хоста.
     * 
     * Эта функция очищает хост, проверяя наличие недопустимых символов, таких как пробелы.
     */
    public String fetchContent(String urlString) throws Exception {
        String cleanedUrl = cleanUrl(urlString);
        URL url = new URL(cleanedUrl);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
        connection.connect();

        if (connection.getResponseCode() != 200) {
            throw new RuntimeException("Failed : HTTP error code : " + connection.getResponseCode());
        }

        BufferedReader br = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder response = new StringBuilder();
        String line;

        while ((line = br.readLine()) != null) {
            response.append(line);
        }
        br.close();

        return response.toString();
    }

    private String cleanUrl(String urlString) throws Exception {
        String encodedUrl = URLEncoder.encode(urlString, "UTF-8");
        return encodedUrl.replace("+", "%20");
    }
}
