import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.regex.Pattern;

public class ClassX {
    private static final String HOST_PATTERN = "^[\\w.-]+$";

    /**
     * Busca conteúdo de uma URL gerada após validar o host.
     * 
     * Esta função sanitiza o host verificando a presença de caracteres inválidos, como espaços.
     * 
     * @param host O host a ser validado.
     * @return Conteúdo da URL ou mensagem de erro.
     */
    public String fetchContent(String host) {
        if (!isValidHost(host)) {
            return "Host inválido.";
        }

        String urlString = "http://" + host;
        StringBuilder content = new StringBuilder();

        try {
            URL url = new URL(urlString);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");

            try (BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                String inputLine;
                while ((inputLine = in.readLine()) != null) {
                    content.append(inputLine).append("\n");
                }
            }
        } catch (MalformedURLException e) {
            return "URL malformada: " + e.getMessage();
        } catch (Exception e) {
            return "Erro ao buscar conteúdo: " + e.getMessage();
        }

        return content.toString();
    }

    private boolean isValidHost(String host) {
        return Pattern.matches(HOST_PATTERN, host) && !host.contains(" ");
    }
}
