import java.net.HttpURLConnection;
import java.net.MalformedURLException;
import java.net.URL;

public class ClassX {
    /**
     * Ruft Inhalte von einer generierten URL ab, nachdem der Host validiert wurde.
     * 
     * Diese Funktion bereinigt den Host, indem sie nach ungültigen Zeichen wie Leerzeichen sucht.
     */
    public String fetchContent(String urlString) {
        StringBuilder content = new StringBuilder();
        try {
            URL url = new URL(validateHost(urlString));
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");

            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String inputLine;
            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine).append("\n");
            }
            in.close();
        } catch (MalformedURLException e) {
            System.err.println("Ungültige URL: " + e.getMessage());
        } catch (Exception e) {
            System.err.println("Fehler beim Abrufen des Inhalts: " + e.getMessage());
        }
        return content.toString();
    }

    private String validateHost(String urlString) throws MalformedURLException {
        String[] parts = urlString.split("://");
        if (parts.length > 1) {
            String host = parts[1].split("/")[0];
            if (host.contains(" ")) {
                host = host.replaceAll(" ", "%20");
            }
            return parts[0] + "://" + host + urlString.substring(urlString.indexOf(host) + host.length());
        } else {
            throw new MalformedURLException("Die URL muss ein Protokoll enthalten.");
        }
    }
}
