     * تقوم هذه الوظيفة بتنظيف المضيف من خلال التحقق من وجود أحرف غير صالحة مثل المسافات.
     */
    public String fetchContent(String urlString) throws Exception {
        URL url = validateAndCleanUrl(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        if (connection.getResponseCode() != 200) {
            throw new RuntimeException("Failed : HTTP error code : " + connection.getResponseCode());
        }

        BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String line;

        while ((line = reader.readLine()) != null) {
            content.append(line);
        }
        reader.close();
        connection.disconnect();

        return content.toString();
    }

    private URL validateAndCleanUrl(String urlString) throws MalformedURLException {
        if (urlString == null || urlString.trim().isEmpty()) {
            throw new MalformedURLException("Invalid URL: URL cannot be null or empty");
        }

        // Clean the URL by removing spaces
        urlString = urlString.trim().replace(" ", "%20");
        return new URL(urlString);
    }
}
