        if (command != null) {
            executeCommand(command, filePath);
        } else {
            System.out.println("No command found for MIME type: " + mimeType);
        }
    }

    private String findMatch(String mimeType) {
        // A simple mapping for demonstration purposes
        switch (mimeType) {
            case "image/jpeg":
                return "xdg-open";
            case "application/pdf":
                return "evince";
            case "text/plain":
                return "gedit";
            default:
                return null;
        }
    }

    private void executeCommand(String command, String filePath) {
        if (command.contains(";") || command.contains("&")) {
            System.out.println("Command injection detected!");
            return;
        }

        ProcessBuilder processBuilder = new ProcessBuilder();
        processBuilder.command(command, filePath);
        try {
            Process process = processBuilder.start();
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            int exitCode = process.waitFor();
            System.out.println("Exited with code: " + exitCode);
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

