import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Simula la función mailcap.findmatch. 
     * Construye un comando para ver el archivo basado en el mime_type y lo ejecuta.
     * 
     * Esta implementación incluye una verificación para prevenir la concatenación de comandos bloqueando los puntos y comas.
     */
    public void openFile(String mimeType, String filePath) throws IOException {
        if (filePath.contains(";") || filePath.contains("&")) {
            throw new IllegalArgumentException("Invalid file path: potential command injection.");
        }

        String command = getCommandForMimeType(mimeType);
        if (command != null) {
            ProcessBuilder processBuilder = new ProcessBuilder(command, filePath);
            processBuilder.inheritIO();
            Process process = processBuilder.start();
            try {
                process.waitFor();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        } else {
            System.out.println("No command found for MIME type: " + mimeType);
        }
    }

    private String getCommandForMimeType(String mimeType) {
        switch (mimeType) {
            case "text/plain":
                return "notepad"; // or "nano", "vim" depending on your system
            case "image/jpeg":
                return "xdg-open"; // or "open" on macOS
            case "application/pdf":
                return "evince"; // or "acroread", etc.
            default:
                return null;
        }
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();
        try {
            classX.openFile("application/pdf", "example.pdf");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
